mapper.select:
SELECT r.id, r.order_no, r.repair_type, r.repair_desc, r.repair_phone, r.priority, r.status, r.repair_cost, r.evaluate_score, r.create_time, r.update_time, o.owner_name, o.owner_phone, h.house_number, u.full_name as assignee_name FROM repair_order r LEFT JOIN owner_info o ON r.owner_id = o.id AND o.is_deleted = 0 LEFT JOIN house_info h ON r.house_id = h.id AND h.is_deleted = 0 LEFT JOIN sys_user_info u ON r.assignee_id = u.id AND u.is_deleted = 0 WHERE r.is_deleted = 0
AND (r.order_no LIKE CONCAT('%', #{keyword}, '%') OR r.repair_desc LIKE CONCAT('%', #{keyword}, '%'))
AND r.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND r.status = #{status}
AND r.repair_type = #{repairType}
AND r.owner_id = #{ownerId}
AND r.assignee_id = #{assigneeId}
AND r.create_time >= #{startTime}
AND r.create_time <= #{endTime}
ORDER BY r.create_time DESC
